  `author` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '小明同学' COMMENT '作者名称',
  `category_id` bigint DEFAULT NULL COMMENT '分类ID',
  `view_count` int DEFAULT '0' COMMENT '浏览量',
