INSERT INTO `blogs` VALUES (1,'Dokcer安装教程（新手向）','详细详细的安装Docker的步骤，提供最能成功的安装方式','<!-- 引入Font Awesome图标库 -->\n<link href=\"https://cdn.jsdelivr.net/npm/font-awesome@4.7.0/css/font-awesome.min.css\" rel=\"stylesheet\">\n\n<style>\n/* 代码高亮样式 */\n.code-keyword { color: #c678dd; }\n.code-command { color: #61afef; }\n.code-parameter { color: #e06c75; }\n.code-string { color: #98c379; }\n.code-comment { color: #5c6370; font-style: italic; }\n\n/* 滚动条美化 */\n::-webkit-scrollbar {\n    width: 8px;\n    height: 8px;\n}\n::-webkit-scrollbar-track {\n    background: #f1f1f1;\n    border-radius: 4px;\n}\n::-webkit-scrollbar-thumb {\n    background: #c1c1c1;\n    border-radius: 4px;\n}\n::-webkit-scrollbar-thumb:hover {\n    background: #a1a1a1;\n}\n\n/* 平滑滚动 */\nhtml {\n    scroll-behavior: smooth;\n}\n\n/* 代码块解释动画样式 */\n.code-explanation {\n    transition: max-height 0.3s ease-out, opacity 0.3s ease-out;\n    overflow: hidden;\n    max-height: 0;\n    opacity: 0;\n}\n\n.code-explanation.visible {\n    max-height: 2000px;\n    opacity: 1;\n}\n\n/* 自定义颜色变量 */\n:root {\n    --primary: #2496ed;\n    --secondary: #36d399;\n    --neutral: #f8fafc;\n    --dark: #1e293b;\n    --code: #1e293b;\n    --explanation: #f1f5f9;\n}\n\n/* 基础样式 */\n.text-primary { color: var(--primary); }\n.bg-primary { background-color: var(--primary); }\n.border-primary { border-color: var(--primary); }\n.text-dark { color: var(--dark); }\n.bg-code { background-color: var(--code); }\n.bg-explanation { background-color: var(--explanation); }\n\n/* 响应式容器 */\n.container {\n    width: 100%;\n    max-width: 1200px;\n    margin: 0 auto;\n    padding: 0 1rem;\n}\n\n/* 常用工具类 */\n.rounded-xl { border-radius: 0.75rem; }\n.rounded-lg { border-radius: 0.5rem; }\n.rounded-t-lg { border-top-left-radius: 0.5rem; border-top-right-radius: 0.5rem; }\n.rounded-b-lg { border-bottom-left-radius: 0.5rem; border-bottom-right-radius: 0.5rem; }\n.shadow-md { box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1); }\n.transition-all { transition: all 0.3s ease; }\n.hover\\:shadow-lg:hover { box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); }\n\n/* 文本样式 */\n.text-2xl { font-size: 1.5rem; line-height: 2rem; }\n.text-3xl { font-size: 1.875rem; line-height: 2.25rem; }\n.text-xl { font-size: 1.25rem; line-height: 1.75rem; }\n.text-lg { font-size: 1.125rem; line-height: 1.75rem; }\n.font-bold { font-weight: 700; }\n.font-semibold { font-weight: 600; }\n.font-medium { font-weight: 500; }\n.font-mono { font-family: Consolas, Monaco, \'Courier New\', monospace; }\n\n/* 间距 */\n.p-6 { padding: 1.5rem; }\n.p-4 { padding: 1rem; }\n.px-4 { padding-left: 1rem; padding-right: 1rem; }\n.py-8 { padding-top: 2rem; padding-bottom: 2rem; }\n.pt-4 { padding-top: 1rem; }\n.pb-8 { padding-bottom: 2rem; }\n.pl-4 { padding-left: 1rem; }\n.pl-6 { padding-left: 1.5rem; }\n.pl-10 { padding-left: 2.5rem; }\n.mb-2 { margin-bottom: 0.5rem; }\n.mb-3 { margin-bottom: 0.75rem; }\n.mb-4 { margin-bottom: 1rem; }\n.mb-6 { margin-bottom: 1.5rem; }\n.mb-8 { margin-bottom: 2rem; }\n.mr-2 { margin-right: 0.5rem; }\n.mr-3 { margin-right: 0.75rem; }\n.mt-1 { margin-top: 0.25rem; }\n\n/* 布局 */\n.flex { display: flex; }\n.grid { display: grid; }\n.grid-cols-1 { grid-template-columns: repeat(1, minmax(0, 1fr)); }\n.items-center { align-items: center; }\n.items-start { align-items: flex-start; }\n.space-y-1 > * + * { margin-top: 0.25rem; }\n.space-y-2 > * + * { margin-top: 0.5rem; }\n.space-y-3 > * + * { margin-top: 0.75rem; }\n.gap-4 { gap: 1rem; }\n\n/* 响应式布局 */\n@media (min-width: 768px) {\n    .md\\:grid-cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n    .md\\:grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n}\n\n/* 边框 */\n.border { border-width: 1px; }\n.border-l-4 { border-left-width: 4px; }\n.border-t-0 { border-top-width: 0; }\n.border-gray-200 { border-color: #e5e7eb; }\n.border-blue-200 { border-color: #bfdbfe; }\n.border-blue-400 { border-color: #60a5fa; }\n.border-amber-200 { border-color: #fde68a; }\n.border-orange-400 { border-color: #fb923c; }\n.border-red-400 { border-color: #f87171; }\n.border-green-200 { border-color: #bbf7d0; }\n.border-green-400 { border-color: #4ade80; }\n.border-yellow-200 { border-color: #fde047; }\n.border-indigo-200 { border-color: #c7d2fe; }\n.border-gray-100 { border-color: #f3f4f6; }\n.border-orange-200 { border-color: #fed7aa; }\n.border-purple-200 { border-color: #e9d5ff; }\n.rounded-r-lg { border-top-right-radius: 0.5rem; border-bottom-right-radius: 0.5rem; }\n\n/* 背景色 */\n.bg-white { background-color: #ffffff; }\n.bg-gray-50 { background-color: #f9fafb; }\n.bg-gray-700 { background-color: #374151; }\n.bg-gray-100 { background-color: #f3f4f6; }\n.bg-blue-50 { background-color: #eff6ff; }\n.bg-amber-50 { background-color: #fffbeb; }\n.bg-green-50 { background-color: #f0fdf4; }\n.bg-green-100 { background-color: #dcfce7; }\n.bg-blue-100 { background-color: #dbeafe; }\n.bg-red-100 { background-color: #fee2e2; }\n.bg-orange-50 { background-color: #fff7ed; }\n.bg-orange-100 { background-color: #fed7aa; }\n.bg-orange-500 { background-color: #f97316; }\n.bg-red-50 { background-color: #fef2f2; }\n.bg-purple-50 { background-color: #faf5ff; }\n.bg-yellow-50 { background-color: #fefce8; }\n.bg-yellow-200 { background-color: #fef08a; }\n.bg-indigo-50 { background-color: #eef2ff; }\n.bg-purple-100 { background-color: #f3e8ff; }\n.bg-gray-900 { background-color: #111827; }\n\n/* 渐变背景 */\n.bg-gradient-to-r { background-image: linear-gradient(to right, var(--tw-gradient-stops)); }\n.from-blue-50 { --tw-gradient-from: #eff6ff; --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to, rgba(239, 246, 255, 0)); }\n.from-green-50 { --tw-gradient-from: #f0fdf4; --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to, rgba(240, 253, 244, 0)); }\n.to-indigo-50 { --tw-gradient-to: #eef2ff; }\n.to-blue-50 { --tw-gradient-to: #eff6ff; }\n.to-green-100 { --tw-gradient-to: #dcfce7; }\n.to-blue-100 { --tw-gradient-to: #dbeafe; }\n.to-purple-100 { --tw-gradient-to: #f3e8ff; }\n.bg-gradient-to-br { background-image: linear-gradient(to bottom right, var(--tw-gradient-stops)); }\n\n/* 文字颜色 */\n.text-gray-600 { color: #4b5563; }\n.text-gray-700 { color: #374151; }\n.text-gray-800 { color: #1f2937; }\n.text-gray-100 { color: #f3f4f6; }\n.text-gray-400 { color: #9ca3af; }\n.text-amber-500 { color: #f59e0b; }\n.text-amber-600 { color: #d97706; }\n.text-amber-700 { color: #b45309; }\n.text-amber-800 { color: #92400e; }\n.text-blue-800 { color: #1e40af; }\n.text-green-500 { color: #22c55e; }\n.text-green-600 { color: #16a34a; }\n.text-green-800 { color: #166534; }\n.text-orange-500 { color: #f97316; }\n.text-orange-600 { color: #ea580c; }\n.text-orange-700 { color: #c2410c; }\n.text-orange-800 { color: #9a3412; }\n.text-red-500 { color: #ef4444; }\n.text-red-800 { color: #991b1b; }\n.text-blue-600 { color: #2563eb; }\n.text-blue-700 { color: #1d4ed8; }\n.text-gray-500 { color: #6b7280; }\n.text-yellow-600 { color: #ca8a04; }\n.text-yellow-700 { color: #a16207; }\n.text-yellow-800 { color: #854d0e; }\n.text-indigo-800 { color: #3730a3; }\n.text-purple-600 { color: #9333ea; }\n.text-purple-700 { color: #7c3aed; }\n.text-purple-800 { color: #6b21a8; }\n.text-green-400 { color: #4ade80; }\n.text-white { color: #ffffff; }\n\n/* 其他 */\n.overflow-x-auto { overflow-x: auto; }\n.leading-relaxed { line-height: 1.625; }\n.list-disc { list-style-type: disc; }\n.pl-5 { padding-left: 1.25rem; }\n\n/* 图标和小组件样式 */\n.fa {\n    display: inline-block;\n    font: normal normal normal 14px/1 FontAwesome;\n    font-size: inherit;\n    text-rendering: auto;\n    -webkit-font-smoothing: antialiased;\n    -moz-osx-font-smoothing: grayscale;\n}\n\n/* Font Awesome图标已通过link标签引入 */\n\n/* 小图标方块样式 */\n.w-4 { width: 1rem; }\n.h-4 { height: 1rem; }\n.w-6 { width: 1.5rem; }\n.h-6 { height: 1.5rem; }\n.w-8 { width: 2rem; }\n.h-8 { height: 2rem; }\n.w-12 { width: 3rem; }\n.h-12 { height: 3rem; }\n.rounded-sm { border-radius: 0.125rem; }\n.rounded-full { border-radius: 9999px; }\n\n/* 文字大小 */\n.text-xs { font-size: 0.75rem; line-height: 1rem; }\n.text-sm { font-size: 0.875rem; line-height: 1.25rem; }\n.text-10px { font-size: 10px; }\n\n/* 定位 */\n.inline-block { display: inline-block; }\n.justify-center { justify-content: center; }\n\n/* 鼠标样式 */\n.cursor-pointer { cursor: pointer; }\n\n/* 额外的颜色和效果 */\n.text-red-500 { color: #ef4444; }\n.hover\\:shadow-lg:hover { box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05); }\n.transition-colors { transition-property: color, background-color, border-color, text-decoration-color, fill, stroke; transition-duration: 0.15s; transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1); }\n\n/* 间距补充 */\n.py-1 { padding-top: 0.25rem; padding-bottom: 0.25rem; }\n.py-2 { padding-top: 0.5rem; padding-bottom: 0.5rem; }\n.px-1 { padding-left: 0.25rem; padding-right: 0.25rem; }\n.mr-1 { margin-right: 0.25rem; }\n.ml-1 { margin-left: 0.25rem; }\n.mt-0\\.5 { margin-top: 0.125rem; }\n.mt-1 { margin-top: 0.25rem; }\n.mb-1 { margin-bottom: 0.25rem; }\n.space-y-0\\.5 > * + * { margin-top: 0.125rem; }\n\n/* 可见性和显示 */\n.visible { visibility: visible; }\n.hidden { display: none; }\n\n/* 自定义按钮样式 */\n.btn {\n    display: inline-flex;\n    align-items: center;\n    padding: 0.5rem 1rem;\n    border-radius: 0.375rem;\n    font-weight: 500;\n    transition: all 0.2s;\n    cursor: pointer;\n    border: none;\n}\n\n.btn-primary {\n    background-color: var(--primary);\n    color: white;\n}\n\n.btn-primary:hover {\n    background-color: #1976d2;\n    transform: translateY(-1px);\n}\n\n/* 返回顶部按钮 */\n#dockerBackToTop {\n    position: fixed;\n    bottom: 30px;\n    right: 30px;\n    z-index: 1000;\n    opacity: 0;\n    visibility: hidden;\n    transition: all 0.3s ease;\n}\n\n#dockerBackToTop.visible {\n    opacity: 1;\n    visibility: visible;\n}\n</style>\n\n<!-- 主要内容 -->\n<div class=\"container mx-auto px-4 pt-4 pb-8\">\n    <!-- 简介部分 -->\n    <section id=\"intro\" class=\"bg-white rounded-xl shadow-md p-6 mb-8 transition-all hover:shadow-lg\">\n        <div style=\"background: linear-gradient(135deg, rgba(36, 150, 237, 0.1), rgba(36, 150, 237, 0.05));\" class=\"p-6 rounded-lg mb-6\">\n            <h2 class=\"text-2xl font-bold mb-4 text-dark\">? Docker安装教程（新手友好版）</h2>\n            <p class=\"mb-4 text-gray-700 leading-relaxed text-lg\">还在为各种环境配置问题头疼吗？还在为\"在我机器上能跑\"的问题抓狂吗？<span class=\"bg-yellow-200 px-2 py-1 rounded font-medium\">Docker来拯救你了！</span></p>\n            <p class=\"mb-4 text-gray-700 leading-relaxed\">网上的Docker安装教程五花八门，有的过于简单一笔带过，有的又复杂得让人望而却步。本教程专为<strong class=\"text-primary\">Linux新手</strong>量身定制，<span class=\"bg-green-100 px-2 py-1 rounded\">每一条命令都有详细解释</span>，让你不仅知其然，更知其所以然。</p>\n            \n            <div class=\"bg-blue-50 border-l-4 border-blue-400 p-4 mt-4 rounded-r-lg\">\n                <p class=\"text-blue-800 font-medium\">? 小贴士：Docker就像是一个超级强大的\"打包盒\"，能把你的应用和所有依赖环境一起打包，不管在哪台机器上都能完美运行！</p>\n            </div>\n        </div>\n        \n        <div class=\"mb-6\">\n            <div class=\"flex items-center mb-4 p-4 bg-gradient-to-r from-blue-50 to-indigo-50 rounded-lg border border-blue-200\">\n                <i class=\"fa fa-check-circle text-primary text-xl mr-3\"></i>\n                <p class=\"font-medium text-lg\">? 本教程适合这些朋友：</p>\n            </div>\n            <ul class=\"space-y-3 pl-4\">\n                <li class=\"flex items-start p-3 bg-orange-50 rounded-lg border-l-4 border-orange-400\">\n                    <i class=\"fa fa-ubuntu text-orange-500 text-lg mt-1 mr-3\"></i>\n                    <div>\n                        <span class=\"font-medium text-gray-800\">Ubuntu系统用户</span>\n                        <p class=\"text-sm text-gray-600 mt-1\">适用于Ubuntu 16.04及以上版本，包括最新的22.04 LTS</p>\n                    </div>\n                </li>\n                <li class=\"flex items-start p-3 bg-red-50 rounded-lg border-l-4 border-red-400\">\n                    <i class=\"fa fa-linux text-red-500 text-lg mt-1 mr-3\"></i>\n                    <div>\n                        <span class=\"font-medium text-gray-800\">CentOS系统用户</span>\n                        <p class=\"text-sm text-gray-600 mt-1\">支持CentOS 7/8，以及RHEL和Fedora等红帽系发行版</p>\n                    </div>\n                </li>\n                <li class=\"flex items-start p-3 bg-green-50 rounded-lg border-l-4 border-green-400\">\n                    <i class=\"fa fa-user text-green-500 text-lg mt-1 mr-3\"></i>\n                    <div>\n                        <span class=\"font-medium text-gray-800\">Linux新手用户</span>\n                        <p class=\"text-sm text-gray-600 mt-1\">刚接触Linux，想学习容器技术的开发者和运维人员</p>\n                    </div>\n                </li>\n            </ul>\n        </div>\n        \n        <div class=\"bg-amber-50 border border-amber-200 rounded-lg p-4\">\n            <div class=\"flex items-center mb-2\">\n                <i class=\"fa fa-clock-o text-amber-600 mr-2\"></i>\n                <span class=\"font-medium text-amber-800\">⏱️ 预计用时：10-15分钟</span>\n            </div>\n            <p class=\"text-amber-700 text-sm\">包括下载、安装、验证的完整流程。建议先通读一遍再开始操作哦！</p>\n        </div>\n    </section>\n\n    <!-- 新版本系统通用安装 -->\n    <section id=\"new-version\" class=\"bg-white rounded-xl shadow-md p-6 mb-8 transition-all hover:shadow-lg\">\n        <h2 class=\"text-2xl font-bold mb-6 text-dark flex items-center\">\n            <i class=\"fa fa-bolt text-primary mr-3 text-xl\"></i>⚡ 一键安装大法（推荐）\n        </h2>\n        \n        <div class=\"bg-gradient-to-r from-green-50 to-blue-50 p-4 rounded-lg mb-6 border border-green-200\">\n            <div class=\"flex items-center mb-2\">\n                <i class=\"fa fa-rocket text-green-600 mr-2\"></i>\n                <span class=\"font-bold text-green-800\">? 这是最简单的方法！</span>\n            </div>\n            <p class=\"text-gray-700 leading-relaxed\">适用于<span class=\"bg-blue-100 px-2 py-1 rounded font-medium\">Ubuntu 16.04+</span>和<span class=\"bg-red-100 px-2 py-1 rounded font-medium\">CentOS 7+</span>等新版本系统。Docker官方提供的自动化脚本，能智能识别你的系统并安装最合适的版本，<strong>真正的一键搞定</strong>！</p>\n        </div>\n        \n        <div class=\"bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-6\">\n            <div class=\"flex items-start\">\n                <i class=\"fa fa-lightbulb text-yellow-600 mr-3 mt-1\"></i>\n                <div>\n                    <p class=\"font-medium text-yellow-800 mb-2\">? 为什么推荐这种方法？</p>\n                    <ul class=\"text-yellow-700 text-sm space-y-1\">\n                        <li>• <strong>自动化程度高</strong>：脚本会自动检测系统版本、架构等信息</li>\n                        <li>• <strong>版本总是最新</strong>：直接从Docker官方仓库获取最新稳定版</li>\n                        <li>• <strong>出错概率低</strong>：经过无数用户验证，兼容性极佳</li>\n                        <li>• <strong>省心省力</strong>：不用记住复杂的仓库地址和配置步骤</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n        \n        <div class=\"mb-8 border-l-4 border-primary pl-6 py-2\">\n            <h3 class=\"text-xl font-semibold mb-4 text-primary flex items-center\">\n                <span class=\"bg-primary text-white rounded-full w-8 h-8 flex items-center justify-center text-sm mr-3\">1</span>\n                ? 获取Docker官方安装脚本\n            </h3>\n            \n            <div class=\"bg-indigo-50 p-4 rounded-lg mb-4 border border-indigo-200\">\n                <p class=\"text-indigo-800 leading-relaxed\">\n                    <strong>? 这一步的作用：</strong>我们要从Docker官网下载一个\"万能安装脚本\"，这个脚本就像一个聪明的管家，会自动识别你的系统版本，然后选择最合适的安装方式。\n                </p>\n            </div>\n            \n            <!-- 代码块容器 -->\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">curl</span> \n                        <span class=\"code-parameter\">-fsSL</span> \n                        <span class=\"code-string\">https://get.docker.com</span> \n                        <span class=\"code-parameter\">-o</span> \n                        <span class=\"code-string\">install-docker.sh</span>\n                    </code>\n                </div>\n                <!-- 解释部分，默认隐藏 -->\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-3\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">? 命令详解（点击展开查看）：</p>\n                    </div>\n                    <div class=\"bg-white p-4 rounded-lg border border-gray-100\">\n                        <ul class=\"space-y-2 text-gray-700\">\n                            <li class=\"flex items-start\">\n                                <span class=\"bg-blue-100 text-blue-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">curl</span>\n                                <span>网络下载神器，比浏览器下载更稳定可靠</span>\n                            </li>\n                            <li class=\"flex items-start\">\n                                <span class=\"bg-green-100 text-green-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">-f</span>\n                                <span><strong>快速失败</strong>：遇到404等错误立即停止，不浪费时间</span>\n                            </li>\n                            <li class=\"flex items-start\">\n                                <span class=\"bg-green-100 text-green-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">-s</span>\n                                <span><strong>静默模式</strong>：不显示下载进度条，保持终端清爽</span>\n                            </li>\n                            <li class=\"flex items-start\">\n                                <span class=\"bg-green-100 text-green-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">-S</span>\n                                <span><strong>智能报错</strong>：虽然静默，但有错误时会告诉你</span>\n                            </li>\n                            <li class=\"flex items-start\">\n                                <span class=\"bg-green-100 text-green-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">-L</span>\n                                <span><strong>自动跳转</strong>：如果网址重定向会自动跟随，很智能！</span>\n                            </li>\n                            <li class=\"flex items-start\">\n                                <span class=\"bg-purple-100 text-purple-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">-o</span>\n                                <span><strong>保存文件</strong>：把下载的脚本保存为 <code class=\"bg-gray-100 px-1 rounded\">install-docker.sh</code></span>\n                            </li>\n                        </ul>\n                    </div>\n                    \n                    <div class=\"mt-4 p-3 bg-blue-50 rounded-lg border border-blue-200\">\n                        <p class=\"text-blue-800 text-sm\">\n                            <i class=\"fa fa-graduation-cap mr-2\"></i>\n                            <strong>小知识：</strong>这个网址 <code>https://get.docker.com</code> 是Docker官方的快速安装入口，全世界的开发者都在用它！\n                        </p>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"bg-orange-50 border border-orange-200 rounded-lg p-4 mb-4\">\n                <div class=\"flex items-start\">\n                    <i class=\"fa fa-exclamation-triangle text-orange-600 mr-3 mt-1\"></i>\n                    <div>\n                        <p class=\"font-medium text-orange-800 mb-2\">? 网络不好？试试国内镜像！</p>\n                        <p class=\"text-orange-700 text-sm leading-relaxed\">\n                            如果你在国内，可能会遇到网络访问较慢的问题。别担心，国内的小伙伴们早就准备好了镜像源！\n                            <span class=\"bg-orange-100 px-2 py-1 rounded font-medium\">DaoCloud</span> 是一个很靠谱的选择。\n                        </p>\n                    </div>\n                </div>\n            </div>\n            \n            <!-- 国内镜像代码块 -->\n            <div class=\"code-container mb-4\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">curl</span> \n                        <span class=\"code-parameter\">-fsSL</span> \n                        <span class=\"code-string\">https://get.daocloud.io/docker</span> \n                        <span class=\"code-parameter\">-o</span> \n                        <span class=\"code-string\">install-docker.sh</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-3\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">? 国内镜像的优势：</p>\n                    </div>\n                    <div class=\"space-y-3\">\n                        <div class=\"bg-green-50 p-3 rounded-lg border border-green-200\">\n                            <p class=\"text-green-800 text-sm\">\n                                <strong>? 速度更快：</strong>服务器在国内，下载速度通常比国外官方源快3-5倍\n                            </p>\n                        </div>\n                        <div class=\"bg-blue-50 p-3 rounded-lg border border-blue-200\">\n                            <p class=\"text-blue-800 text-sm\">\n                                <strong>?️ 更稳定：</strong>避免网络波动导致的下载中断问题\n                            </p>\n                        </div>\n                        <div class=\"bg-purple-50 p-3 rounded-lg border border-purple-200\">\n                            <p class=\"text-purple-800 text-sm\">\n                                <strong>? 移动友好：</strong>对移动网络和校园网更友好\n                            </p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"mb-8 border-l-4 border-primary pl-6 py-2\">\n            <h3 class=\"text-xl font-semibold mb-4 text-primary flex items-center\">\n                <span class=\"bg-primary text-white rounded-full w-8 h-8 flex items-center justify-center text-sm mr-3\">2</span>\n                ? 执行安装脚本（见证奇迹的时刻）\n            </h3>\n            \n            <div class=\"bg-green-50 p-4 rounded-lg mb-4 border border-green-200\">\n                <p class=\"text-green-800 leading-relaxed\">\n                    <strong>? 这一步的魔法：</strong>现在轮到脚本大显身手了！它会像一个经验丰富的系统管理员一样，自动检测你的系统环境，下载合适的Docker版本，配置相关依赖，一气呵成完成整个安装过程。\n                </p>\n            </div>\n            \n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">sh</span> \n                        <span class=\"code-string\">install-docker.sh</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-3\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">? 命令拆解（点击展开查看）：</p>\n                    </div>\n                    <div class=\"bg-white p-4 rounded-lg border border-gray-100\">\n                        <ul class=\"space-y-3 text-gray-700\">\n                            <li class=\"flex items-start\">\n                                <span class=\"bg-red-100 text-red-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">sudo</span>\n                                <div>\n                                    <strong>超级用户权限</strong>：安装软件需要修改系统文件，必须要管理员权限\n                                    <p class=\"text-xs text-gray-500 mt-1\">? 就像装修房子需要房主同意一样</p>\n                                </div>\n                            </li>\n                            <li class=\"flex items-start\">\n                                <span class=\"bg-blue-100 text-blue-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">sh</span>\n                                <div>\n                                    <strong>脚本执行器</strong>：告诉系统这是一个shell脚本，需要用shell来执行\n                                    <p class=\"text-xs text-gray-500 mt-1\">? 相当于\"导演，开始拍摄！\"</p>\n                                </div>\n                            </li>\n                            <li class=\"flex items-start\">\n                                <span class=\"bg-purple-100 text-purple-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">install-docker.sh</span>\n                                <div>\n                                    <strong>安装脚本文件</strong>：我们刚下载的Docker安装程序\n                                    <p class=\"text-xs text-gray-500 mt-1\">? 里面包含了所有安装步骤的自动化指令</p>\n                                </div>\n                            </li>\n                        </ul>\n                    </div>\n                    \n                    <div class=\"mt-4 p-3 bg-yellow-50 rounded-lg border border-yellow-200\">\n                        <div class=\"flex items-start\">\n                            <i class=\"fa fa-lightbulb text-yellow-600 mr-2 mt-1\"></i>\n                            <div>\n                                <p class=\"text-yellow-800 text-sm font-medium mb-1\">? 安装过程中你会看到：</p>\n                                <ul class=\"text-yellow-700 text-xs space-y-0.5\">\n                                    <li>• ? 检测系统版本和架构信息</li>\n                                    <li>• ? 添加Docker官方软件源</li>\n                                    <li>• ⬇️ 下载Docker相关组件</li>\n                                    <li>• ⚙️ 自动配置服务和权限</li>\n                                    <li>• ✅ 启动Docker服务</li>\n                                </ul>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            \n            <div class=\"bg-blue-50 border border-blue-200 rounded-lg p-4\">\n                <div class=\"flex items-start\">\n                    <i class=\"fa fa-coffee text-blue-600 mr-3 mt-1\"></i>\n                    <div>\n                        <p class=\"font-medium text-blue-800 mb-2\">☕ 耐心等待片刻</p>\n                        <p class=\"text-blue-700 text-sm leading-relaxed\">\n                            整个安装过程通常需要3-10分钟，具体时间取决于你的网络速度和系统性能。可以去泡杯咖啡，回来就装好了！\n                            <span class=\"bg-blue-100 px-2 py-1 rounded font-medium\">看到\"Docker安装完成\"的提示就大功告成啦！</span>\n                        </p>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"bg-green-50 p-4 rounded-lg mb-6\">\n            <div class=\"flex items-center mb-2\">\n                <i class=\"fa fa-lightbulb text-green-600 mr-2\"></i>\n                <p class=\"font-medium text-green-600\">提示：</p>\n            </div>\n            <p class=\"text-gray-700\">脚本会自动检测您的系统版本并安装合适的Docker版本，安装过程可能需要几分钟时间。</p>\n        </div>\n    </section>\n\n    <!-- 前期准备工作 -->\n    <section id=\"preparation\" class=\"bg-white rounded-xl shadow-md p-6 mb-8 transition-all hover:shadow-lg\">\n        <h2 class=\"text-2xl font-bold mb-6 text-dark flex items-center\">\n            <i class=\"fa fa-wrench text-primary mr-3 text-xl\"></i>? 安装前的小检查（避免踩坑）\n        </h2>\n        \n        <div class=\"bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6\">\n            <p class=\"text-blue-800 leading-relaxed\">\n                <strong>? 为什么要做准备工作？</strong>就像开车前要检查油量和轮胎一样，安装Docker前也要确保你的系统环境符合要求。\n                这样能避免安装过程中遇到奇怪的错误，<span class=\"bg-blue-100 px-2 py-1 rounded font-medium\">让整个过程更顺畅</span>！\n            </p>\n        </div>\n        \n        <div class=\"mb-8\">\n            <h3 class=\"text-xl font-semibold mb-4 text-primary flex items-center\">\n                <span class=\"bg-green-500 text-white rounded-full w-8 h-8 flex items-center justify-center text-sm mr-3\">✓</span>\n                ? 系统要求检查清单\n            </h3>\n            \n            <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4\">\n                <div class=\"bg-gradient-to-br from-green-50 to-green-100 border border-green-200 rounded-lg p-4\">\n                    <div class=\"flex items-center mb-3\">\n                        <i class=\"fa fa-microchip text-green-600 text-lg mr-2\"></i>\n                        <span class=\"font-medium text-green-800\">架构要求</span>\n                    </div>\n                    <p class=\"text-green-700 text-sm mb-2\"><strong>64位操作系统</strong></p>\n                    <p class=\"text-green-600 text-xs\">现在的电脑基本都是64位，很少有32位的了</p>\n                </div>\n                \n                <div class=\"bg-gradient-to-br from-blue-50 to-blue-100 border border-blue-200 rounded-lg p-4\">\n                    <div class=\"flex items-center mb-3\">\n                        <i class=\"fa fa-cogs text-blue-600 text-lg mr-2\"></i>\n                        <span class=\"font-medium text-blue-800\">内核版本</span>\n                    </div>\n                    <p class=\"text-blue-700 text-sm mb-2\"><strong>3.10以上</strong></p>\n                    <p class=\"text-blue-600 text-xs\">CentOS 7/Ubuntu 14.04及以上都满足</p>\n                </div>\n                \n                <div class=\"bg-gradient-to-br from-purple-50 to-purple-100 border border-purple-200 rounded-lg p-4\">\n                    <div class=\"flex items-center mb-3\">\n                        <i class=\"fa fa-memory text-purple-600 text-lg mr-2\"></i>\n                        <span class=\"font-medium text-purple-800\">内存要求</span>\n                    </div>\n                    <p class=\"text-purple-700 text-sm mb-2\"><strong>至少1GB可用</strong></p>\n                    <p class=\"text-purple-600 text-xs\">推荐2GB以上，运行更流畅</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"mb-6\">\n            <h3 class=\"text-xl font-semibold mb-4 text-primary flex items-center\">\n                <span class=\"bg-primary text-white rounded-full w-8 h-8 flex items-center justify-center text-sm mr-3\">?</span>\n                ? 快速检查系统版本\n            </h3>\n            \n            <div class=\"bg-indigo-50 p-4 rounded-lg mb-4 border border-indigo-200\">\n                <p class=\"text-indigo-800 leading-relaxed\">\n                    <strong>? 为什么要检查？</strong>不同的系统版本对Docker的支持程度不同，提前确认可以避免后续的兼容性问题。\n                    这个命令会告诉你当前系统的内核版本，<span class=\"bg-indigo-100 px-2 py-1 rounded font-medium\">就像查看手机系统版本一样简单</span>。\n                </p>\n            </div>\n            \n            <div class=\"code-container mb-4\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">uname</span> \n                        <span class=\"code-parameter\">-r</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-3\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">? 命令拆解：</p>\n                    </div>\n                    <div class=\"bg-white p-4 rounded-lg border border-gray-100\">\n                        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-4\">\n                            <div class=\"flex items-start\">\n                                <span class=\"bg-blue-100 text-blue-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">uname</span>\n                                <div>\n                                    <strong>系统信息查看器</strong>\n                                    <p class=\"text-xs text-gray-500 mt-1\">Unix Name的缩写，获取系统信息</p>\n                                </div>\n                            </div>\n                            <div class=\"flex items-start\">\n                                <span class=\"bg-green-100 text-green-800 px-2 py-1 rounded text-xs font-mono mr-3 mt-0.5\">-r</span>\n                                <div>\n                                    <strong>显示内核版本</strong>\n                                    <p class=\"text-xs text-gray-500 mt-1\">Release的意思，只显示内核版本号</p>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                    \n                    <div class=\"mt-4 p-3 bg-green-50 rounded-lg border border-green-200\">\n                        <p class=\"text-green-800 text-sm font-medium mb-2\">? 预期输出示例：</p>\n                        <div class=\"bg-gray-900 text-green-400 p-2 rounded font-mono text-xs\">\n                            5.15.0-56-generic  # Ubuntu 22.04<br>\n                            4.18.0-348.el8.x86_64  # CentOS 8<br>\n                            3.10.0-1160.el7.x86_64  # CentOS 7\n                        </div>\n                        <p class=\"text-green-700 text-xs mt-2\">只要版本号大于3.10就可以安装Docker</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"bg-amber-50 border border-amber-200 rounded-lg p-4\">\n            <div class=\"flex items-start\">\n                <i class=\"fa fa-exclamation-triangle text-amber-600 mr-3 mt-1\"></i>\n                <div>\n                    <p class=\"font-medium text-amber-800 mb-2\">⚠️ 系统版本过低怎么办？</p>\n                    <div class=\"text-amber-700 text-sm space-y-2\">\n                        <p>如果你的内核版本低于3.10，建议：</p>\n                        <ul class=\"list-disc pl-5 space-y-1\">\n                            <li><strong>优先选择：</strong>升级到更新的系统版本（如CentOS 7+, Ubuntu 16.04+）</li>\n                            <li><strong>临时方案：</strong>升级内核版本（需要一定Linux经验）</li>\n                            <li><strong>简单方案：</strong>使用云服务器，通常都是新版本系统</li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Ubuntu安装方法 -->\n    <section id=\"ubuntu\" class=\"bg-white rounded-xl shadow-md p-6 mb-8 transition-all hover:shadow-lg\">\n        <h2 class=\"text-2xl font-bold mb-6 text-dark flex items-center\">\n            <div class=\"w-6 h-6 bg-orange-500 rounded-sm mr-3 flex items-center justify-center\">\n                <span class=\"text-white text-sm font-bold\">U</span>\n            </div>\n            Ubuntu系统安装Docker\n        </h2>\n        \n        <div class=\"mb-8 border-l-4 border-primary pl-4 py-1\">\n            <h3 class=\"text-xl font-semibold mb-4 text-primary\">方法一：使用apt命令安装（推荐）</h3>\n            \n            <p class=\"mb-4 text-gray-700\">首先更新软件包索引：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">apt</span> \n                        <span class=\"code-parameter\">update</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• apt</strong>：Ubuntu的包管理工具</li>\n                        <li><strong class=\"text-primary\">• update</strong>：更新可用软件包的列表</li>\n                    </ul>\n                </div>\n            </div>\n\n            <p class=\"mb-4 text-gray-700\">安装必要的软件包：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">apt</span> \n                        <span class=\"code-parameter\">install</span> \n                        <span class=\"code-parameter\">-y</span>\n                        <span class=\"code-string\">docker.io</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• install</strong>：安装软件包</li>\n                        <li><strong class=\"text-primary\">• -y</strong>：自动确认安装，不需要手动输入y</li>\n                        <li><strong class=\"text-primary\">• docker.io</strong>：Docker社区版的包名</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"mb-8 border-l-4 border-primary pl-4 py-1\">\n            <h3 class=\"text-xl font-semibold mb-4 text-primary\">方法二：添加Docker官方源安装（最新版本）</h3>\n            \n            <p class=\"mb-4 text-gray-700\">1. 安装依赖包：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">apt</span> \n                        <span class=\"code-parameter\">install</span> \n                        <span class=\"code-string\">apt-transport-https</span> \n                        <span class=\"code-string\">ca-certificates</span> \n                        <span class=\"code-string\">curl</span> \n                        <span class=\"code-string\">gnupg</span> \n                        <span class=\"code-string\">lsb-release</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• apt-transport-https</strong>：允许apt通过HTTPS下载</li>\n                        <li><strong class=\"text-primary\">• ca-certificates</strong>：证书管理</li>\n                        <li><strong class=\"text-primary\">• curl</strong>：下载工具</li>\n                        <li><strong class=\"text-primary\">• gnupg</strong>：密钥管理</li>\n                        <li><strong class=\"text-primary\">• lsb-release</strong>：系统信息查看</li>\n                    </ul>\n                </div>\n            </div>\n\n            <p class=\"mb-4 text-gray-700\">2. 添加Docker官方GPG密钥：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">curl</span> \n                        <span class=\"code-parameter\">-fsSL</span> \n                        <span class=\"code-string\">https://download.docker.com/linux/ubuntu/gpg</span> \n                        <span class=\"code-parameter\">|</span> \n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">gpg</span> \n                        <span class=\"code-parameter\">--dearmor</span> \n                        <span class=\"code-parameter\">-o</span> \n                        <span class=\"code-string\">/usr/share/keyrings/docker-archive-keyring.gpg</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• curl -fsSL</strong>：下载GPG密钥</li>\n                        <li><strong class=\"text-primary\">• |</strong>：管道符，将前一个命令的输出传给下一个命令</li>\n                        <li><strong class=\"text-primary\">• gpg --dearmor</strong>：将密钥转换为二进制格式</li>\n                        <li><strong class=\"text-primary\">• -o</strong>：输出到指定文件</li>\n                    </ul>\n                </div>\n            </div>\n\n            <p class=\"mb-4 text-gray-700\">3. 添加Docker软件源：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">echo</span> \n                        <span class=\"code-string\">\"deb [arch=amd64 signed-by=/usr/share/keyrings/docker-archive-keyring.gpg] https://download.docker.com/linux/ubuntu $(lsb_release -cs) stable\"</span> \n                        <span class=\"code-parameter\">|</span> \n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">tee</span> \n                        <span class=\"code-string\">/etc/apt/sources.list.d/docker.list</span> \n                        <span class=\"code-parameter\">></span> \n                        <span class=\"code-string\">/dev/null</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• echo</strong>：输出文本</li>\n                        <li><strong class=\"text-primary\">• $(lsb_release -cs)</strong>：获取Ubuntu版本代号</li>\n                        <li><strong class=\"text-primary\">• tee</strong>：将输出同时写入文件和标准输出</li>\n                        <li><strong class=\"text-primary\">• > /dev/null</strong>：忽略标准输出</li>\n                    </ul>\n                </div>\n            </div>\n\n            <p class=\"mb-4 text-gray-700\">4. 更新软件包列表并安装Docker：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">apt</span> \n                        <span class=\"code-parameter\">update</span> \n                        <span class=\"code-parameter\">&&</span> \n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">apt</span> \n                        <span class=\"code-parameter\">install</span> \n                        <span class=\"code-string\">docker-ce</span> \n                        <span class=\"code-string\">docker-ce-cli</span> \n                        <span class=\"code-string\">containerd.io</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• &&</strong>：逻辑与，前一个命令成功后才执行下一个</li>\n                        <li><strong class=\"text-primary\">• docker-ce</strong>：Docker社区版引擎</li>\n                        <li><strong class=\"text-primary\">• docker-ce-cli</strong>：Docker命令行工具</li>\n                        <li><strong class=\"text-primary\">• containerd.io</strong>：容器运行时</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- CentOS安装方法 -->\n    <section id=\"centos\" class=\"bg-white rounded-xl shadow-md p-6 mb-8 transition-all hover:shadow-lg\">\n        <h2 class=\"text-2xl font-bold mb-6 text-dark flex items-center\">\n            <i class=\"fa fa-linux text-primary mr-3 text-xl\"></i>CentOS系统安装Docker\n        </h2>\n        \n        <div class=\"mb-8 border-l-4 border-primary pl-4 py-1\">\n            <h3 class=\"text-xl font-semibold mb-4 text-primary\">方法一：使用yum安装（推荐）</h3>\n            \n            <p class=\"mb-4 text-gray-700\">安装必要的工具：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">yum</span> \n                        <span class=\"code-parameter\">install</span> \n                        <span class=\"code-parameter\">-y</span> \n                        <span class=\"code-string\">yum-utils</span> \n                        <span class=\"code-string\">device-mapper-persistent-data</span> \n                        <span class=\"code-string\">lvm2</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• yum</strong>：CentOS的包管理工具</li>\n                        <li><strong class=\"text-primary\">• yum-utils</strong>：yum工具包</li>\n                        <li><strong class=\"text-primary\">• device-mapper-persistent-data</strong>：设备映射器</li>\n                        <li><strong class=\"text-primary\">• lvm2</strong>：逻辑卷管理</li>\n                    </ul>\n                </div>\n            </div>\n\n            <p class=\"mb-4 text-gray-700\">添加Docker官方yum源：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">yum-config-manager</span> \n                        <span class=\"code-parameter\">--add-repo</span> \n                        <span class=\"code-string\">https://download.docker.com/linux/centos/docker-ce.repo</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• yum-config-manager</strong>：yum源管理工具</li>\n                        <li><strong class=\"text-primary\">• --add-repo</strong>：添加软件源</li>\n                        <li><strong class=\"text-primary\">• docker-ce.repo</strong>：Docker官方源配置文件</li>\n                    </ul>\n                </div>\n            </div>\n\n            <p class=\"mb-4 text-gray-700\">安装Docker：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">yum</span> \n                        <span class=\"code-parameter\">install</span> \n                        <span class=\"code-parameter\">-y</span> \n                        <span class=\"code-string\">docker-ce</span> \n                        <span class=\"code-string\">docker-ce-cli</span> \n                        <span class=\"code-string\">containerd.io</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">安装的组件说明：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• docker-ce</strong>：Docker社区版引擎</li>\n                        <li><strong class=\"text-primary\">• docker-ce-cli</strong>：Docker命令行工具</li>\n                        <li><strong class=\"text-primary\">• containerd.io</strong>：容器运行时</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- 启动和验证 -->\n    <section id=\"startup\" class=\"bg-white rounded-xl shadow-md p-6 mb-8 transition-all hover:shadow-lg\">\n        <h2 class=\"text-2xl font-bold mb-6 text-dark flex items-center\">\n            <i class=\"fa fa-play-circle text-primary mr-3 text-xl\"></i>启动Docker并验证安装\n        </h2>\n        \n        <div class=\"mb-8 border-l-4 border-primary pl-4 py-1\">\n            <h3 class=\"text-xl font-semibold mb-4 text-primary\">启动Docker服务</h3>\n            \n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">systemctl</span> \n                        <span class=\"code-parameter\">start</span> \n                        <span class=\"code-string\">docker</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• systemctl</strong>：系统服务管理工具</li>\n                        <li><strong class=\"text-primary\">• start</strong>：启动服务</li>\n                        <li><strong class=\"text-primary\">• docker</strong>：Docker服务名称</li>\n                    </ul>\n                </div>\n            </div>\n\n            <p class=\"mb-4 text-gray-700\">设置Docker开机自启：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">systemctl</span> \n                        <span class=\"code-parameter\">enable</span> \n                        <span class=\"code-string\">docker</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• enable</strong>：设置服务开机自启动</li>\n                        <li>这样系统重启后Docker会自动启动</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"mb-8 border-l-4 border-primary pl-4 py-1\">\n            <h3 class=\"text-xl font-semibold mb-4 text-primary\">验证Docker安装</h3>\n            \n            <p class=\"mb-4 text-gray-700\">检查Docker版本：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">docker</span> \n                        <span class=\"code-parameter\">--version</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">预期输出类似：</p>\n                    </div>\n                    <div class=\"bg-gray-100 p-3 rounded font-mono text-sm\">\n                        Docker version 20.10.17, build 100c701\n                    </div>\n                </div>\n            </div>\n\n            <p class=\"mb-4 text-gray-700\">运行测试容器：</p>\n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">docker</span> \n                        <span class=\"code-parameter\">run</span> \n                        <span class=\"code-string\">hello-world</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• docker run</strong>：运行容器命令</li>\n                        <li><strong class=\"text-primary\">• hello-world</strong>：Docker官方测试镜像</li>\n                        <li>如果看到\"Hello from Docker!\"说明安装成功</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"bg-green-50 p-4 rounded-lg\">\n            <div class=\"flex items-center mb-2\">\n                <i class=\"fa fa-check-circle text-green-600 mr-2\"></i>\n                <p class=\"font-medium text-green-600\">恭喜！</p>\n            </div>\n            <p class=\"text-gray-700\">如果以上命令都能正常执行，说明Docker已经成功安装并可以正常使用了。</p>\n        </div>\n    </section>\n\n    <!-- 用户权限配置 -->\n    <section id=\"permissions\" class=\"bg-white rounded-xl shadow-md p-6 mb-8 transition-all hover:shadow-lg\">\n        <h2 class=\"text-2xl font-bold mb-6 text-dark flex items-center\">\n            <i class=\"fa fa-users text-primary mr-3 text-xl\"></i>用户权限配置（可选）\n        </h2>\n        \n        <p class=\"mb-6 text-gray-700 leading-relaxed\">默认情况下，只有root用户和docker组的用户能够运行Docker命令。为了让普通用户也能使用Docker，可以将用户添加到docker组。</p>\n        \n        <div class=\"mb-8 border-l-4 border-primary pl-4 py-1\">\n            <h3 class=\"text-xl font-semibold mb-4 text-primary\">添加用户到docker组</h3>\n            \n            <div class=\"code-container mb-6\">\n                <div class=\"bg-code rounded-t-lg p-4 overflow-x-auto font-mono text-sm text-gray-100 flex items-center\">\n                    <i class=\"fa fa-terminal text-gray-400 mr-3\"></i>\n                    <code>\n                        <span class=\"code-command\">sudo</span> \n                        <span class=\"code-command\">usermod</span> \n                        <span class=\"code-parameter\">-aG</span> \n                        <span class=\"code-string\">docker</span> \n                        <span class=\"code-string\">$USER</span>\n                    </code>\n                </div>\n                <div class=\"code-explanation bg-explanation rounded-b-lg border border-t-0 border-gray-200 p-4\">\n                    <div class=\"flex items-center mb-2\">\n                        <i class=\"fa fa-info-circle text-primary mr-2\"></i>\n                        <p class=\"font-medium\">命令解释：</p>\n                    </div>\n                    <ul class=\"space-y-1 text-gray-700 pl-6\">\n                        <li><strong class=\"text-primary\">• usermod</strong>：修改用户属性的命令</li>\n                        <li><strong class=\"text-primary\">• -aG</strong>：将用户添加到指定组，保留原有组</li>\n                        <li><strong class=\"text-primary\">• docker</strong>：Docker用户组名</li>\n                        <li><strong class=\"text-primary\">• $USER</strong>：当前登录用户的用户名变量</li>\n                    </ul>\n                </div>\n            </div>\n\n            <div class=\"bg-amber-50 p-4 rounded-lg\">\n                <div class=\"flex items-center mb-2\">\n                    <i class=\"fa fa-exclamation-triangle text-amber-500 mr-2\"></i>\n                    <p class=\"font-medium text-amber-500\">注意：</p>\n                </div>\n                <p class=\"text-gray-700\">执行此命令后需要注销并重新登录，或者重启系统才能生效。之后就可以不使用sudo直接运行docker命令了。</p>\n            </div>\n        </div>\n    </section>\n\n    <!-- 常见问题解答 -->\n    <section id=\"qa\" class=\"bg-white rounded-xl shadow-md p-6 mb-8 transition-all hover:shadow-lg\">\n        <h2 class=\"text-2xl font-bold mb-6 text-dark flex items-center\">\n            <i class=\"fa fa-question-circle text-primary mr-3 text-xl\"></i>常见问题解答\n        </h2>\n        \n        <div class=\"space-y-6\">\n            <div class=\"border border-gray-200 rounded-lg p-4\">\n                <h3 class=\"font-semibold text-lg mb-2 text-primary\">Q: 安装过程中出现网络错误怎么办？</h3>\n                <p class=\"text-gray-700 mb-2\">A: 可以尝试以下方法：</p>\n                <ul class=\"space-y-1 text-gray-700 pl-6\">\n                    <li>• 检查网络连接是否正常</li>\n                    <li>• 使用国内镜像源（如DaoCloud镜像）</li>\n                    <li>• 配置HTTP代理（如果在企业网络环境中）</li>\n                </ul>\n            </div>\n\n            <div class=\"border border-gray-200 rounded-lg p-4\">\n                <h3 class=\"font-semibold text-lg mb-2 text-primary\">Q: Docker服务启动失败怎么办？</h3>\n                <p class=\"text-gray-700 mb-2\">A: 检查以下几点：</p>\n                <ul class=\"space-y-1 text-gray-700 pl-6\">\n                    <li>• 确保系统内核版本满足要求（3.10以上）</li>\n                    <li>• 检查是否有其他容器运行时冲突</li>\n                    <li>• 查看系统日志：<code class=\"bg-gray-100 px-1 rounded\">journalctl -u docker</code></li>\n                </ul>\n            </div>\n\n            <div class=\"border border-gray-200 rounded-lg p-4\">\n                <h3 class=\"font-semibold text-lg mb-2 text-primary\">Q: 如何完全卸载Docker？</h3>\n                <p class=\"text-gray-700 mb-2\">A: Ubuntu系统：</p>\n                <div class=\"bg-gray-100 p-3 rounded font-mono text-sm mb-2\">\n                    sudo apt remove docker-ce docker-ce-cli containerd.io<br>\n                    sudo rm -rf /var/lib/docker\n                </div>\n                <p class=\"text-gray-700 mb-2\">CentOS系统：</p>\n                <div class=\"bg-gray-100 p-3 rounded font-mono text-sm\">\n                    sudo yum remove docker-ce docker-ce-cli containerd.io<br>\n                    sudo rm -rf /var/lib/docker\n                </div>\n            </div>\n\n            <div class=\"border border-gray-200 rounded-lg p-4\">\n                <h3 class=\"font-semibold text-lg mb-2 text-primary\">Q: 如何配置Docker镜像加速？</h3>\n                <p class=\"text-gray-700 mb-2\">A: 可以配置国内镜像源加速下载：</p>\n                <div class=\"bg-gray-100 p-3 rounded font-mono text-sm\">\n                    sudo mkdir -p /etc/docker<br>\n                    sudo tee /etc/docker/daemon.json &lt;&lt;-\'EOF\'<br>\n                    {<br>\n                    &nbsp;&nbsp;\"registry-mirrors\": [\"https://mirror.ccs.tencentyun.com\"]<br>\n                    }<br>\n                    EOF<br>\n                    sudo systemctl restart docker\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- 总结 -->\n    <section class=\"bg-white rounded-xl shadow-md p-6 mb-8 transition-all hover:shadow-lg\">\n        <h2 class=\"text-2xl font-bold mb-6 text-dark flex items-center\">\n            <i class=\"fa fa-flag-checkered text-primary mr-3 text-xl\"></i>总结\n        </h2>\n        \n        <div class=\"bg-blue-50 p-6 rounded-lg\">\n            <p class=\"text-gray-700 leading-relaxed mb-4\">\n                通过本教程，您已经学会了在Ubuntu和CentOS系统上安装Docker的多种方法。无论是使用系统包管理器的简单安装，还是添加官方源的完整安装，都能让您成功运行Docker容器。\n            </p>\n            <p class=\"text-gray-700 leading-relaxed\">\n                建议新手从系统默认源的安装方法开始，熟悉后再尝试官方源的最新版本安装。安装完成后记得验证安装结果，确保Docker服务正常运行。\n            </p>\n        </div>\n        \n        <div class=\"mt-6 flex items-center justify-center\">\n            <p class=\"text-gray-600 flex items-center\">\n                <i class=\"fa fa-heart text-red-500 mr-2\"></i>\n                希望这个教程对您有帮助！\n            </p>\n        </div>\n    </section>\n</div>\n\n<!-- 返回顶部按钮 -->\n<button id=\"dockerBackToTop\" class=\"btn btn-primary rounded-full w-12 h-12 flex items-center justify-center shadow-lg\">\n    <i class=\"fa fa-chevron-up\"></i>\n</button>\n\n<script>\n// 代码解释展开/收起功能\ndocument.addEventListener(\'DOMContentLoaded\', function() {\n    // 为每个代码块添加点击事件\n    const codeBlocks = document.querySelectorAll(\'.bg-code\');\n    \n    codeBlocks.forEach(block => {\n        // 添加视觉提示\n        block.style.cursor = \'pointer\';\n        block.title = \'点击查看命令解释\';\n        \n        // 添加一个小图标提示\n        const hint = document.createElement(\'div\');\n        hint.className = \'text-xs text-gray-400 mt-1\';\n        hint.innerHTML = \'<i class=\"fa fa-info-circle mr-1\"></i>点击查看详细解释\';\n        block.appendChild(hint);\n        \n        block.addEventListener(\'click\', function() {\n            const explanation = this.nextElementSibling;\n            if (explanation && explanation.classList.contains(\'code-explanation\')) {\n                explanation.classList.toggle(\'visible\');\n                \n                // 更新提示文字\n                if (explanation.classList.contains(\'visible\')) {\n                    hint.innerHTML = \'<i class=\"fa fa-eye-slash mr-1\"></i>点击隐藏解释\';\n                } else {\n                    hint.innerHTML = \'<i class=\"fa fa-info-circle mr-1\"></i>点击查看详细解释\';\n                }\n            }\n        });\n    });\n\n    // 返回顶部按钮功能\n    const backToTopBtn = document.getElementById(\'dockerBackToTop\');\n    \n    if (backToTopBtn) {\n        // 监听滚动事件\n        window.addEventListener(\'scroll\', function() {\n            if (window.pageYOffset > 300) {\n                backToTopBtn.classList.add(\'visible\');\n            } else {\n                backToTopBtn.classList.remove(\'visible\');\n            }\n        });\n\n        // 点击返回顶部\n        backToTopBtn.addEventListener(\'click\', function(e) {\n            e.preventDefault();\n            e.stopPropagation();\n            window.scrollTo({\n                top: 0,\n                behavior: \'smooth\'\n            });\n        });\n    }\n\n    console.log(\'Docker tutorial script loaded successfully\');\n});\n</script>','Rush',1,22,0,'2025-08-16 09:00:00','2025-09-12 02:31:44'),(2,'Cloudflare Tunnel 配置指南','使用Tunnel技术，让你未备案的域名别人可以访问','<!-- Cloudflare Tunnel 配置指南 - 博客文章内容 -->\n<style>\n/* 文章专用样式 - 与博客系统兼容 */\n.tunnel-guide {\n    font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', \'PingFang SC\', \'Hiragino Sans GB\', \'Microsoft YaHei\', sans-serif;\n    line-height: 1.7;\n    color: #333;\n}\n\n.tunnel-guide .article-header {\n    text-align: center;\n    padding: 30px 0;\n    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n    color: white;\n    border-radius: 15px;\n    margin-bottom: 30px;\n}\n\n.tunnel-guide .article-header h1 {\n    font-size: 2.2rem;\n    margin-bottom: 10px;\n    text-shadow: 2px 2px 4px rgba(0,0,0,0.3);\n}\n\n.tunnel-guide .article-header p {\n    font-size: 1.1rem;\n    opacity: 0.9;\n}\n\n.tunnel-guide .architecture {\n    text-align: center;\n    background: #f8f9fa;\n    padding: 20px;\n    border-radius: 10px;\n    margin: 20px 0;\n    border-left: 4px solid #007bff;\n}\n\n.tunnel-guide .architecture code {\n    font-size: 1.1rem;\n    color: #495057;\n    background: none;\n}\n\n.tunnel-guide .section {\n    margin-bottom: 40px;\n}\n\n.tunnel-guide .section h2 {\n    color: #2c3e50;\n    font-size: 1.8rem;\n    margin-bottom: 20px;\n    padding-bottom: 10px;\n    border-bottom: 3px solid #3498db;\n    display: flex;\n    align-items: center;\n}\n\n.tunnel-guide .section h3 {\n    color: #34495e;\n    font-size: 1.3rem;\n    margin: 25px 0 15px 0;\n    display: flex;\n    align-items: center;\n}\n\n.tunnel-guide .emoji {\n    margin-right: 10px;\n    font-size: 1.2em;\n}\n\n.tunnel-guide .step-card {\n    background: #f8f9fa;\n    border-radius: 10px;\n    padding: 20px;\n    margin: 15px 0;\n    border-left: 4px solid #28a745;\n    transition: transform 0.2s ease, box-shadow 0.2s ease;\n}\n\n.tunnel-guide .step-card:hover {\n    transform: translateY(-2px);\n    box-shadow: 0 8px 25px rgba(0,0,0,0.1);\n}\n\n.tunnel-guide .code-block {\n    background: #2d3748;\n    color: #e2e8f0;\n    padding: 20px;\n    border-radius: 8px;\n    margin: 15px 0;\n    overflow-x: auto;\n    border-left: 4px solid #4299e1;\n    position: relative;\n}\n\n.tunnel-guide .code-block::before {\n    content: attr(data-lang);\n    position: absolute;\n    top: 5px;\n    right: 10px;\n    font-size: 0.8rem;\n    color: #a0aec0;\n    text-transform: uppercase;\n}\n\n.tunnel-guide .code-block code {\n    font-family: \'Cascadia Code\', \'Fira Code\', \'Monaco\', \'Consolas\', monospace;\n    font-size: 0.9rem;\n    line-height: 1.5;\n}\n\n.tunnel-guide .warning {\n    background: #fff3cd;\n    border: 1px solid #ffeaa7;\n    border-left: 4px solid #fdcb6e;\n    border-radius: 8px;\n    padding: 15px;\n    margin: 15px 0;\n}\n\n.tunnel-guide .warning .warning-title {\n    font-weight: bold;\n    color: #856404;\n    margin-bottom: 8px;\n    display: flex;\n    align-items: center;\n}\n\n.tunnel-guide .success {\n    background: #d4edda;\n    border: 1px solid #c3e6cb;\n    border-left: 4px solid #28a745;\n    border-radius: 8px;\n    padding: 15px;\n    margin: 15px 0;\n}\n\n.tunnel-guide .info {\n    background: #d1ecf1;\n    border: 1px solid #b6d4dd;\n    border-left: 4px solid #17a2b8;\n    border-radius: 8px;\n    padding: 15px;\n    margin: 15px 0;\n}\n\n.tunnel-guide .checklist {\n    background: #f8f9fa;\n    border-radius: 8px;\n    padding: 20px;\n    margin: 15px 0;\n}\n\n.tunnel-guide .checklist ul {\n    list-style: none;\n    padding-left: 0;\n}\n\n.tunnel-guide .checklist li {\n    margin: 8px 0;\n    display: flex;\n    align-items: center;\n}\n\n.tunnel-guide .checklist li::before {\n    content: \"✅\";\n    margin-right: 10px;\n}\n\n.tunnel-guide .command-group {\n    background: #ffffff;\n    border: 1px solid #e1e5e9;\n    border-radius: 8px;\n    margin: 15px 0;\n    overflow: hidden;\n}\n\n.tunnel-guide .command-header {\n    background: #f1f3f4;\n    padding: 10px 15px;\n    font-weight: bold;\n    color: #495057;\n    border-bottom: 1px solid #e1e5e9;\n}\n\n.tunnel-guide .command-content {\n    padding: 0;\n}\n\n.tunnel-guide .advantages {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n    gap: 20px;\n    margin: 20px 0;\n}\n\n.tunnel-guide .advantage-card {\n    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n    color: white;\n    padding: 20px;\n    border-radius: 15px;\n    text-align: center;\n    transition: transform 0.2s ease;\n}\n\n.tunnel-guide .advantage-card:hover {\n    transform: translateY(-5px);\n}\n\n.tunnel-guide .toc {\n    background: #f8f9fa;\n    border-radius: 10px;\n    padding: 20px;\n    margin-bottom: 30px;\n    border-left: 4px solid #007bff;\n}\n\n.tunnel-guide .toc h3 {\n    margin-top: 0;\n    color: #495057;\n}\n\n.tunnel-guide .toc ul {\n    list-style: none;\n    padding-left: 0;\n}\n\n.tunnel-guide .toc li {\n    margin: 8px 0;\n}\n\n.tunnel-guide .toc a {\n    color: #007bff;\n    text-decoration: none;\n    padding: 5px 10px;\n    border-radius: 5px;\n    transition: background-color 0.2s ease;\n}\n\n.tunnel-guide .toc a:hover {\n    background-color: #e9ecef;\n}\n\n@media (max-width: 768px) {\n    .tunnel-guide .advantages {\n        grid-template-columns: 1fr;\n    }\n    \n    .tunnel-guide .article-header h1 {\n        font-size: 1.8rem;\n    }\n}\n</style>\n\n<div class=\"tunnel-guide\">\n    <div class=\"article-header\">\n        <h1><span class=\"emoji\">?</span>Cloudflare Tunnel 配置指南</h1>\n        <p>Windows管理端 + 云端Linux服务器架构</p>\n    </div>\n\n    <div class=\"toc\">\n        <h3><span class=\"emoji\">?</span>目录导航</h3>\n        <ul>\n            <li><a href=\"#architecture\">架构说明</a></li>\n            <li><a href=\"#phase1\">阶段一：Windows端配置</a></li>\n            <li><a href=\"#phase2\">阶段二：Linux服务器配置</a></li>\n            <li><a href=\"#phase3\">阶段三：应用运行确认</a></li>\n            <li><a href=\"#phase4\">阶段四：验证和调试</a></li>\n            <li><a href=\"#management\">管理和维护</a></li>\n            <li><a href=\"#checklist\">快速检查清单</a></li>\n        </ul>\n    </div>\n\n    <div id=\"architecture\" class=\"section\">\n        <h2><span class=\"emoji\">?️</span>架构说明</h2>\n        <div class=\"architecture\">\n            <code>Windows电脑 (管理端) ←→ Cloudflare ←→ 云端Linux服务器 (应用运行)</code>\n        </div>\n        <div class=\"advantages\">\n            <div class=\"advantage-card\">\n                <h4>✅ 零成本</h4>\n                <p>完全免费使用</p>\n            </div>\n            <div class=\"advantage-card\">\n                <h4>? 全球加速</h4>\n                <p>Cloudflare CDN加速</p>\n            </div>\n            <div class=\"advantage-card\">\n                <h4>? 自动HTTPS</h4>\n                <p>免费SSL证书</p>\n            </div>\n            <div class=\"advantage-card\">\n                <h4>?️ DDoS防护</h4>\n                <p>自带安全防护</p>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"phase1\" class=\"section\">\n        <h2><span class=\"emoji\">?</span>阶段一：Windows电脑上的初始配置</h2>\n        \n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>1. 下载Windows版本的cloudflared</h3>\n            <ul>\n                <li>访问：<strong>https://github.com/cloudflare/cloudflared/releases</strong></li>\n                <li>下载：<code>cloudflared-windows-amd64.exe</code></li>\n                <li>重命名为：<code>cloudflared.exe</code></li>\n                <li>放在文件夹：<code>C:\\cloudflared\\</code></li>\n            </ul>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>2. 打开PowerShell/CMD（管理员权限）</h3>\n            <div class=\"code-block\" data-lang=\"cmd\">\n                <code>cd C:\\cloudflared</code>\n            </div>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>3. 登录Cloudflare账号</h3>\n            <div class=\"code-block\" data-lang=\"cmd\">\n                <code>cloudflared.exe tunnel login</code>\n            </div>\n            <div class=\"info\">\n                <strong>说明：</strong>会打开浏览器，登录您的Cloudflare账号，选择您的域名进行授权。登录成功后会生成证书文件 <code>cert.pem</code>\n            </div>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>4. 创建Tunnel</h3>\n            <div class=\"code-block\" data-lang=\"cmd\">\n                <code>cloudflared.exe tunnel create myblog</code>\n            </div>\n            <div class=\"warning\">\n                <div class=\"warning-title\"><span class=\"emoji\">⚠️</span>重要</div>\n                <ul>\n                    <li>会返回Tunnel ID，例如：<code>1234abcd-5678-90ef-ghij-klmnopqrstuv</code></li>\n                    <li><strong>请记录这个ID，后面要用</strong></li>\n                    <li>会生成凭证文件：<code>1234abcd-5678-90ef-ghij-klmnopqrstuv.json</code></li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>5. 配置DNS记录</h3>\n            <p>在Cloudflare网页端（<strong>https://dash.cloudflare.com</strong>）：</p>\n            <ul>\n                <li>进入您的域名 → DNS → Records</li>\n                <li>添加CNAME记录：</li>\n            </ul>\n            \n            <div class=\"command-group\">\n                <div class=\"command-header\">根域名记录</div>\n                <div class=\"command-content\">\n                    <div class=\"code-block\" data-lang=\"dns\">\n                        <code>类型: CNAME\n名称: @ (根域名)\n内容: 1234abcd-5678-90ef-ghij-klmnopqrstuv.cfargotunnel.com\n代理状态: 已代理（橙色云朵）</code>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"phase2\" class=\"section\">\n        <h2><span class=\"emoji\">?️</span>阶段二：云端Linux服务器配置</h2>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>1. 在Linux服务器上安装cloudflared</h3>\n            <p>通过SSH连接到您的云服务器，然后执行：</p>\n            <div class=\"code-block\" data-lang=\"bash\">\n                <code># 下载Linux版本\ncurl -L https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64 -o cloudflared\n\n# 设置权限并移动到系统路径\nchmod +x cloudflared\nsudo mv cloudflared /usr/local/bin/\n\n# 验证安装\ncloudflared --version</code>\n            </div>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>2. 创建cloudflared配置目录</h3>\n            <div class=\"code-block\" data-lang=\"bash\">\n                <code>mkdir -p ~/.cloudflared</code>\n            </div>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>3. 从Windows传输证书文件到Linux服务器</h3>\n            \n            <div class=\"command-group\">\n                <div class=\"command-header\">方法一：使用SCP（推荐）</div>\n                <div class=\"command-content\">\n                    <div class=\"code-block\" data-lang=\"powershell\">\n                        <code># 替换为您的实际信息\nscp C:\\cloudflared\\cert.pem username@your-server-ip:~/.cloudflared/\nscp C:\\cloudflared\\1234abcd-5678-90ef-ghij-klmnopqrstuv.json username@your-server-ip:~/.cloudflared/</code>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"command-group\">\n                <div class=\"command-header\">方法二：使用WinSCP图形界面</div>\n                <div class=\"command-content\">\n                    <ul>\n                        <li>下载WinSCP软件</li>\n                        <li>连接到您的云服务器</li>\n                        <li>将证书文件上传到 <code>~/.cloudflared/</code> 目录</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">⚙️</span>4. 在Linux服务器创建配置文件</h3>\n            <div class=\"code-block\" data-lang=\"bash\">\n                <code>nano ~/.cloudflared/config.yml</code>\n            </div>\n            \n            <p><strong>内容如下：</strong></p>\n            <div class=\"code-block\" data-lang=\"yaml\">\n                <code>tunnel: myblog\ncredentials-file: ~/.cloudflared/1234abcd-5678-90ef-ghij-klmnopqrstuv.json\n\ningress:\n  - hostname: yourdomain.com  # 替换为您的实际域名\n    service: http://localhost:8080\n  - hostname: www.yourdomain.com\n    service: http://localhost:8080\n  - service: http_status:404</code>\n            </div>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>5. 在Linux服务器上运行tunnel</h3>\n            <div class=\"code-block\" data-lang=\"bash\">\n                <code># 测试运行\ncloudflared tunnel --config ~/.cloudflared/config.yml run myblog\n\n# 如果测试成功，设置为后台服务\nsudo cloudflared service install --config ~/.cloudflared/config.yml\nsudo systemctl start cloudflared\nsudo systemctl enable cloudflared</code>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"phase3\" class=\"section\">\n        <h2><span class=\"emoji\">✅</span>阶段三：确保应用正常运行</h2>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>1. 确认Spring Boot应用运行</h3>\n            <p>在您的Linux服务器上：</p>\n            <div class=\"code-block\" data-lang=\"bash\">\n                <code>cd /path/to/your/project\ndocker compose up -d\ndocker compose ps  # 查看服务状态</code>\n            </div>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>2. 测试本地连接</h3>\n            <div class=\"code-block\" data-lang=\"bash\">\n                <code>curl http://localhost:8080</code>\n            </div>\n            <div class=\"success\">\n                <strong>期望结果：</strong>应该能看到您的应用响应。\n            </div>\n        </div>\n    </div>\n\n    <div id=\"phase4\" class=\"section\">\n        <h2><span class=\"emoji\">?</span>阶段四：验证和调试</h2>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>1. 检查tunnel状态</h3>\n            <p>在Linux服务器上：</p>\n            <div class=\"code-block\" data-lang=\"bash\">\n                <code>sudo systemctl status cloudflared\njournalctl -u cloudflared -f  # 查看实时日志</code>\n            </div>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>2. 访问测试</h3>\n            <ul>\n                <li>浏览器访问：<code>https://yourdomain.com</code></li>\n                <li>应该能看到您的Spring Boot应用</li>\n            </ul>\n        </div>\n\n        <div class=\"step-card\">\n            <h3><span class=\"emoji\">?</span>3. 故障排查命令</h3>\n            <div class=\"code-block\" data-lang=\"bash\">\n                <code># 检查端口占用\nnetstat -tlnp | grep 8080\n\n# 检查Docker服务\ndocker compose logs app\n\n# 测试tunnel连接\ncloudflared tunnel info myblog</code>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"management\" class=\"section\">\n        <h2><span class=\"emoji\">⚙️</span>管理和维护</h2>\n\n        <div class=\"command-group\">\n            <div class=\"command-header\">Windows端管理命令</div>\n            <div class=\"command-content\">\n                <div class=\"code-block\" data-lang=\"cmd\">\n                    <code># 查看所有tunnel\ncloudflared.exe tunnel list\n\n# 删除tunnel（如果需要）\ncloudflared.exe tunnel delete myblog\n\n# 查看tunnel信息\ncloudflared.exe tunnel info myblog</code>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"command-group\">\n            <div class=\"command-header\">Linux服务器端管理</div>\n            <div class=\"command-content\">\n                <div class=\"code-block\" data-lang=\"bash\">\n                    <code># 重启tunnel服务\nsudo systemctl restart cloudflared\n\n# 查看服务日志\njournalctl -u cloudflared --since \"10 minutes ago\"\n\n# 停止服务\nsudo systemctl stop cloudflared</code>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"command-group\">\n            <div class=\"command-header\">自启动服务设置</div>\n            <div class=\"command-content\">\n                <div class=\"code-block\" data-lang=\"bash\">\n                    <code># 设置Docker自启动\nsudo systemctl enable docker\nsudo systemctl enable docker.socket\n\n# 设置Cloudflared自启动\nsudo systemctl enable cloudflared\n\n# 检查自启动状态\nsudo systemctl is-enabled docker\nsudo systemctl is-enabled cloudflared</code>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"checklist\" class=\"section\">\n        <h2><span class=\"emoji\">⚡</span>快速检查清单</h2>\n        <div class=\"checklist\">\n            <ul>\n                <li>Windows上成功创建tunnel和DNS配置</li>\n                <li>证书文件正确传输到Linux服务器</li>\n                <li>Linux服务器上cloudflared服务运行正常</li>\n                <li>Spring Boot应用在8080端口正常运行</li>\n                <li>DNS记录生效（可用 <code>nslookup yourdomain.com</code> 检查）</li>\n                <li>服务设置为开机自启动</li>\n                <li>通过域名能够正常访问应用</li>\n            </ul>\n        </div>\n\n        <div class=\"success\">\n            <h4>? 完成后的优势</h4>\n            <ul>\n                <li><strong>全球访问：</strong>通过Cloudflare的全球CDN加速</li>\n                <li><strong>自动HTTPS：</strong>免费SSL证书</li>\n                <li><strong>DDoS保护：</strong>Cloudflare自带防护</li>\n                <li><strong>无需备案：</strong>绕过备案限制</li>\n                <li><strong>动态IP支持：</strong>服务器IP变化也不影响</li>\n                <li><strong>自动运行：</strong>开机自启，无需手动管理</li>\n            </ul>\n        </div>\n    </div>\n</div>\n\n<script>\n// 平滑滚动效果\ndocument.querySelectorAll(\'a[href^=\"#\"]\').forEach(anchor => {\n    anchor.addEventListener(\'click\', function (e) {\n        e.preventDefault();\n        const target = document.querySelector(this.getAttribute(\'href\'));\n        if (target) {\n            target.scrollIntoView({\n                behavior: \'smooth\',\n                block: \'start\'\n            });\n        }\n    });\n});\n\n// 代码块复制功能\ndocument.querySelectorAll(\'.tunnel-guide .code-block\').forEach(block => {\n    block.addEventListener(\'click\', function() {\n        const code = this.querySelector(\'code\').textContent;\n        navigator.clipboard.writeText(code).then(() => {\n            // 创建提示\n            const toast = document.createElement(\'div\');\n            toast.textContent = \'已复制到剪贴板！\';\n            toast.style.cssText = `\n                position: fixed;\n                top: 20px;\n                right: 20px;\n                background: #28a745;\n                color: white;\n                padding: 10px 20px;\n                border-radius: 5px;\n                z-index: 1000;\n                animation: slideIn 0.3s ease;\n            `;\n            document.body.appendChild(toast);\n            setTimeout(() => toast.remove(), 2000);\n        });\n    });\n});\n\n// 添加CSS动画\nif (!document.querySelector(\'#tunnel-guide-animations\')) {\n    const style = document.createElement(\'style\');\n    style.id = \'tunnel-guide-animations\';\n    style.textContent = `\n        @keyframes slideIn {\n            from { transform: translateX(100%); opacity: 0; }\n            to { transform: translateX(0); opacity: 1; }\n        }\n    `;\n    document.head.appendChild(style);\n}\n</script>','Rush',3,3,0,'2025-09-12 01:38:00','2025-09-12 02:37:35');
