  `blog_id` bigint NOT NULL COMMENT '文章ID',
  `parent_id` bigint DEFAULT NULL COMMENT '父评论ID（用于回复）',
  `nickname` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评论者昵称',
