  `user_role` enum('guest','blogger','reader','admin') COLLATE utf8mb4_unicode_ci DEFAULT 'guest' COMMENT '用户角色：guest-游客，blogger-博主，reader-读者，admin-管理员',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评论内容',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '评论时间',
  PRIMARY KEY (`id`),
  KEY `idx_blog_id` (`blog_id`),
